pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Restrict to a wide admissible domain; amount can be any value that msg.value could take
        bound(amount, 0, type(uint256).max);

        // Ensure the timestamp check passes by warping to the future
        vm.warp(block.timestamp + 1);

        // Provide the fuzzed amount to the caller
        vm.deal(address(this), amount);

        bool ok;
        // Try calling the fallback with the fuzzed amount
        try c.fallback{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: if the call did not revert, the amount sent must be exactly 10 ether
        assertTrue(!ok || amount == 10 ether);
    }
}

