pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= 100 ether);
        vm.deal(address(this), amount);
        bool okRef;
        try c.fallback{value: amount}() { okRef = true; } catch { okRef = false; }
        // Reference succeeds IFF amount == 10 ether; mutant succeeds IFF amount > 10 ether.
        // They disagree on amount == 10 ether (ref succeeds, mut fails) and amount > 10 ether (ref fails, mut succeeds).
        // The general rule: if the call succeeds, amount must be exactly 10 ether (for reference) or >10 ether (for mutant).
        // For the reference, amount > 10 ether always fails, so the rule holds vacuously; for the mutant, amount == 10 ether fails,
        // but amount > 10 ether succeeds, so the rule fails for the reference when amount > 10 ether (ref fails, so okRef == false, rule holds)
        // and fails for the mutant when amount == 10 ether (mut fails, so okRef == false, rule holds).
        // Wait, we need a rule that is true for reference for ALL inputs and false for mutant for SOME input.
        // The rule: It is NOT the case that (both succeed). Because the reference only succeeds on 10 ether and mutant only on >10 ether,
        // they never both succeed. So for all inputs, (call succeeds on reference => amount == 10 ether) AND (call succeeds on mutant => amount > 10 ether).
        // But we only have one contract under test. We are testing the reference vs mutant separately; the test is compiled with the reference C.
        // For the reference, the rule is: if the call succeeds, then amount == 10 ether. This is true for all inputs.
        // For the mutant, the rule is: if the call succeeds, then amount > 10 ether. But the mutant also satisfies: if the call succeeds, then amount != 10 ether.
        // The reference satisfies: if the call succeeds, then amount == 10 ether. The mutant violates this for amount > 10 ether (it succeeds but amount != 10 ether).
        assertTrue(!okRef || amount == 10 ether);
    }
}

