pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 value, uint64 blockNumber, uint64 pastBlockTimeSeed, uint256 ethToSeed) public {
        // Admissible domain: value can be anything; blockNumber anything;
        // pastBlockTimeSeed is a timestamp we can use to set block.timestamp to something later.
        uint256 amount = uint256(value);
        vm.assume(ethToSeed > amount);
        // Ensure block.timestamp > pastBlockTimeSeed so that require(block.timestamp > pastBlockTime) passes.
        uint256 ts = uint256(pastBlockTimeSeed) + 1;
        // We also need to ensure a past block time is set for the first require to pass on a succeeding call.
        // We'll call once with 10 ether in reference style, but we'll do it programmatically.
        vm.deal(address(this), ethToSeed);
        // First, set an initial pastBlockTime by calling with 10 ether so the timestamp check passes.
        vm.warp(ts);
        vm.roll(blockNumber);
        bool okInit;
        try c.fallback{value: 10 ether}() { okInit = true; } catch { okInit = false; }
        if (okInit) {
            // Now call with the fuzzed amount
            vm.warp(ts + 1); // advance time so timestamp > pastBlockTime
            vm.roll(blockNumber + 1);
            bool ok;
            try c.fallback{value: amount}() { ok = true; } catch { ok = false; }
            if (ok) {
                uint256 bal = address(c).balance;
                // Invariant: if the call succeeded and the contract has a non-zero balance,
                // then block.timestamp must be strictly greater than pastBlockTime.
                if (bal > 0) {
                    assertTrue(block.timestamp > c.pastBlockTime());
                } else {
                    assertTrue(true); // balance is zero, no requirement on pastBlockTime.
                }
            } else {
                assertTrue(true); // call reverted, no requirement.
            }
        } else {
            assertTrue(true); // initial call failed, cannot test.
        }
    }
}

