pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address sender, uint256 warpTo, uint256 blockNum) public {
        vm.assume(sender != address(0));
        vm.assume(amount == 10 ether);
        vm.assume(warpTo > 0);
        vm.assume(blockNum >= 0);
        vm.assume(sender.code.length == 0);
        vm.warp(warpTo);
        vm.roll(blockNum);
        vm.deal(sender, amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(sender);
        (bool ok,) = address(c).call{value: amount}("");
        assertTrue(ok);
        uint256 balanceAfter = address(c).balance;
        // Invariant: On the reference, the balance change can be 0 (if transfer happens) or +10 ether (if no transfer).
        // On the buggy version (transfer removed), it is always exactly +10 ether.
        // So the invariant "balanceAfter != balanceBefore + 10 ether" holds for reference (at least when transfer triggers),
        // but breaks for buggy version every time.
        // Assert that the balance did NOT increase by exactly 10 ether (reference sometimes violates, buggy always violates).
        // Actually, we need an invariant the reference ALWAYS satisfies and buggy breaks.
        // Reference always satisfies: balanceAfter == balanceBefore || balanceAfter == 0.
        // Buggy always: balanceAfter == balanceBefore + 10 ether.
        // So reference never: balanceAfter == balanceBefore + 10 ether when transfer triggers?
        // But transfer triggers only when block.number % 15 == 0.
        // We cannot control fuzz to always hit that.
        // A simpler invariant: The balance after a fallback call is never strictly greater than before + 10 ether (trivial).
        // But buggy never violates that either.
        // The difference: buggy never transfers, so balance always increases by 10 ether.
        // Reference may transfer everything, so balance can become 0.
        // So invariant "balanceAfter == balanceBefore + 10 ether" is true for buggy always, but false for reference sometimes.
        // We must assert something that reference ALWAYS satisfies and buggy ALWAYS violates for SOME input.
        // A better invariant: The balance after the call can be zero (reference can transfer all) OR can be balanceBefore+10.
        // But buggy balance is always balanceBefore+10, never zero.
        // So "balanceAfter != 0" is always true for buggy, but reference may have balanceAfter == 0.
        // So assertTrue(balanceAfter == 0) would fail for buggy (since never zero), pass for reference sometimes.
        // But we need the property that reference ALWAYS satisfies.
        // Reference: if the fallback succeeds, balanceAfter can be 0 or balanceBefore+10. It never exceeds balanceBefore+10.
        // Buggy: balanceAfter always equals balanceBefore+10.
        // A property reference always satisfies: "balanceAfter <= balanceBefore + 10 ether". Buggy also satisfies that.
        // We must identify a property that is true for ALL inputs on reference but false for buggy on at least one input.
        // Observe: Buggy never sends Ether. So after a call, the contract's balance is always exactly previous balance + 10.
        // Reference may send all Ether away. So the balance after call can be less than previous balance + 10.
        // So: "balanceAfter != balanceBefore + 10 ether" is NOT true for reference all the time (it is true only when transfer triggers, but false when it doesn't).
        // Problem: we need a universal property on reference, so it must hold for every call, regardless of block.number % 15.
        // The only thing reference guarantees: balanceAfter is either balanceBefore (if transfer happened) or balanceBefore+10 (if not). But that's not a simple single equality.
        // Could use: address(c).balance % 10 ether == 0? Not helpful.
        // Use the fact that in buggy, balance strictly increases by 10 ether. In reference, it can stay same or increase, but can also decrease when transfer happens.
        // A universal invariant on reference: "The contract's ether balance is always a multiple of 10 ether if only fallback calls are made?" Not true if initial balance is zero and we send 10, balance becomes 10 (multiple), if transfer happens it becomes 0 (multiple). So it's always multiple of 10 ether. Buggy also multiple of 10 ether.
        // Another: total received ether = sum of 10 ether calls. Buggy also.
        // We need to detect the transfer removal. The transfer sends all balance. So on reference, after a transfer, balance becomes 0. On buggy, balance never becomes 0 unless initial was 0 and no calls.
        // So if we start with zero balance, after one call with block.number%15==0, reference balance becomes 0, buggy becomes 10 ether. So "balanceAfter != 0" is true for buggy, false for reference. But "balanceAfter != 0" is not universally true for reference; it's false when transfer happens. That's the opposite.
        // We assert a property that reference ALWAYS satisfies. If we assert "balanceAfter == 0 || balanceAfter == balanceBefore + 10 ether", that holds for reference always (assuming no other interactions). Buggy always satisfies balanceAfter == balanceBefore+10 ether, which is a subset. So reference satisfies the disjunction always. But buggy also satisfies the disjunction (since it always satisfies the second part). So no.
        // Consider: reference can have balanceAfter == 0. Buggy cannot have balanceAfter == 0 after a call unless initial balance was -10 ether impossible. So if we start with zero, after one call that triggers transfer, reference balance 0, buggy balance 10. So "balanceAfter == 0" is a property that reference sometimes satisfies, buggy never. That's not universal.
        // We need a property that reference ALWAYS satisfies and buggy ALWAYS violates for SOME input. "Always violates" means there exists at least one input where property fails.
        // Consider the property: "The change in contract balance is never exactly 10 ether." For reference, when transfer doesn't trigger, change is +10 ether, violates. When transfer triggers, change is -initial?... Let's compute: Suppose initial balance B. After call value 10, balance becomes B+10. Then if transfer triggers, send all balance, so balance becomes 0. So net change = -B. So if B>0, change is negative. So reference can have change +10 (if no transfer) or negative (if transfer). So "change != +10" fails sometimes for reference. So not universal.
        // What about property: "The contract balance after a call is strictly less than balanceBefore + 10 ether"? That holds for reference when transfer triggers (balance becomes 0 < B+10), but fails when transfer doesn't trigger (balance == B+10). So not universal.
        // The only universal property of reference given this logic is: "After a fallback call, the balance is either the previous balance or the previous balance plus 10 ether or 0 (if transfer sent all)." But we cannot express fuzzy logic easily.
        // Perhaps we can use the fact that the buggy version NEVER sends Ether out. So its balance is monotonically increasing by exactly 10 each call. Reference balance may go down to 0. Therefore, if we make two calls, the buggy balance will be 20 ether, reference could be 0 or 10 or 20 depending on transfers. Not deterministic.
        // To expose difference, we can force the transfer to happen by setting block.number % 15 == 0. But we cannot control fuzzer to always give us block.number % 15 == 0 because we can bound blockNumber to multiples of 15. We can use vm.assume(blockNumber % 15 == 0) to restrict to those cases. That is allowed: vm.assume restricting domain. Then on reference, transfer always triggers. Then after a call, reference balance becomes 0. Buggy balance becomes previous+10. So after one call, reference balance 0, buggy balance 10. Then we can assert "balanceAfter == 0". For reference, it's always true (due to assumption). For buggy, it's always false. That's a property that reference ALWAYS satisfies (given the domain restriction) and buggy ALWAYS violates. That works.
        // So we can restrict blockNumber to be a multiple of 15. Then invariant: after any fallback call, the contract's balance is zero. Reference: true because transfer sends all. Buggy: false because it never sends. So assertTrue(balanceAfter == 0).
        // This satisfies: universal over admissible domain (block.number % 15 == 0). Buggy fails for all such inputs.

        vm.assume(blockNum % 15 == 0);
        assertTrue(balanceAfter == 0);
    }
}

