pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 timestamp, uint256 amount) public {
        // Restrict to admissible domain: exactly 10 ether and increasing timestamp
        amount = bound(amount, 10 ether, 10 ether);
        vm.assume(timestamp > c.pastBlockTime());

        // Set block context
        vm.roll(blockNum);
        vm.warp(timestamp);

        // Fund an EOA to send 10 ether
        address sender = address(0x1234);
        vm.deal(sender, amount);

        // Record balance before
        uint256 balanceBefore = address(c).balance;

        // Trigger fallback
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok, "fallback reverted");

        uint256 balanceAfter = address(c).balance;

        // The buggy version never transfers out; the reference transfers out only when blockNum % 15 == 0.
        // The balance can decrease only under that condition.
        // If balance decreased, blockNum % 15 must be zero.
        if (balanceAfter < balanceBefore) {
            assertTrue(blockNum % 15 == 0);
        } else {
            // No decrease: trivially true
            assertTrue(true);
        }
    }
}

